BEGIN;
CREATE OR REPLACE FUNCTION public.has_tenant_permission(p_tenant_id uuid,p_permission_key text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.clinic_users cu JOIN public.role_permissions rp ON rp.role_id=cu.role_id JOIN public.permissions p ON p.id=rp.permission_id WHERE cu.auth_user_id=auth.uid() AND cu.tenant_id=p_tenant_id AND cu.is_active AND p.permission_key=p_permission_key) OR EXISTS(SELECT 1 FROM public.clinic_user_permissions up JOIN public.permissions p ON p.id=up.permission_id JOIN public.clinic_users cu ON cu.id=up.user_id WHERE cu.auth_user_id=auth.uid() AND up.tenant_id=p_tenant_id AND up.granted AND cu.is_active AND p.permission_key=p_permission_key) OR EXISTS(SELECT 1 FROM public.clinic_user_permission_overrides ov JOIN public.permissions p ON p.id=ov.permission_id JOIN public.clinic_users cu ON cu.id=ov.user_id WHERE cu.auth_user_id=auth.uid() AND ov.tenant_id=p_tenant_id AND ov.granted AND cu.is_active AND p.permission_key=p_permission_key); $$;
REVOKE ALL ON FUNCTION public.has_tenant_permission(uuid,text) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.has_tenant_permission(uuid,text) TO authenticated;
DROP POLICY IF EXISTS rls_roles_custom_insert ON public.roles;DROP POLICY IF EXISTS rls_roles_custom_update ON public.roles;DROP POLICY IF EXISTS rls_roles_custom_delete ON public.roles;
CREATE POLICY rls_roles_custom_insert ON public.roles FOR INSERT TO authenticated WITH CHECK(is_system_role=false AND tenant_id=get_current_tenant_id() AND has_tenant_permission(get_current_tenant_id(),'roles:manage'));
CREATE POLICY rls_roles_custom_update ON public.roles FOR UPDATE TO authenticated USING(is_system_role=false AND tenant_id=get_current_tenant_id() AND has_tenant_permission(get_current_tenant_id(),'roles:manage')) WITH CHECK(is_system_role=false AND tenant_id=get_current_tenant_id() AND has_tenant_permission(get_current_tenant_id(),'roles:manage'));
CREATE POLICY rls_roles_custom_delete ON public.roles FOR DELETE TO authenticated USING(is_system_role=false AND tenant_id=get_current_tenant_id() AND has_tenant_permission(get_current_tenant_id(),'roles:manage'));
DROP POLICY IF EXISTS rls_role_permissions_custom_insert ON public.role_permissions;DROP POLICY IF EXISTS rls_role_permissions_custom_update ON public.role_permissions;DROP POLICY IF EXISTS rls_role_permissions_custom_delete ON public.role_permissions;
CREATE POLICY rls_role_permissions_custom_insert ON public.role_permissions FOR INSERT TO authenticated WITH CHECK(EXISTS(SELECT 1 FROM public.roles r WHERE r.id=role_id AND r.is_system_role=false AND r.tenant_id=get_current_tenant_id()) AND has_tenant_permission(get_current_tenant_id(),'roles:manage'));
CREATE POLICY rls_role_permissions_custom_update ON public.role_permissions FOR UPDATE TO authenticated USING(EXISTS(SELECT 1 FROM public.roles r WHERE r.id=role_id AND r.is_system_role=false AND r.tenant_id=get_current_tenant_id()) AND has_tenant_permission(get_current_tenant_id(),'roles:manage')) WITH CHECK(EXISTS(SELECT 1 FROM public.roles r WHERE r.id=role_id AND r.is_system_role=false AND r.tenant_id=get_current_tenant_id()) AND has_tenant_permission(get_current_tenant_id(),'roles:manage'));
CREATE POLICY rls_role_permissions_custom_delete ON public.role_permissions FOR DELETE TO authenticated USING(EXISTS(SELECT 1 FROM public.roles r WHERE r.id=role_id AND r.is_system_role=false AND r.tenant_id=get_current_tenant_id()) AND has_tenant_permission(get_current_tenant_id(),'roles:manage'));
DROP POLICY IF EXISTS rls_clinic_user_permission_overrides_insert ON public.clinic_user_permission_overrides;DROP POLICY IF EXISTS rls_clinic_user_permission_overrides_update ON public.clinic_user_permission_overrides;DROP POLICY IF EXISTS rls_clinic_user_permission_overrides_delete ON public.clinic_user_permission_overrides;
CREATE POLICY rls_clinic_user_permission_overrides_insert ON public.clinic_user_permission_overrides FOR INSERT TO authenticated WITH CHECK(tenant_id=get_current_tenant_id() AND has_tenant_permission(get_current_tenant_id(),'overrides:manage'));
CREATE POLICY rls_clinic_user_permission_overrides_update ON public.clinic_user_permission_overrides FOR UPDATE TO authenticated USING(tenant_id=get_current_tenant_id() AND has_tenant_permission(get_current_tenant_id(),'overrides:manage')) WITH CHECK(tenant_id=get_current_tenant_id() AND has_tenant_permission(get_current_tenant_id(),'overrides:manage'));
CREATE POLICY rls_clinic_user_permission_overrides_delete ON public.clinic_user_permission_overrides FOR DELETE TO authenticated USING(tenant_id=get_current_tenant_id() AND has_tenant_permission(get_current_tenant_id(),'overrides:manage'));
DROP POLICY IF EXISTS ajm1_cup_write ON public.clinic_user_permissions;CREATE POLICY ajm1_cup_write ON public.clinic_user_permissions FOR ALL TO authenticated USING(tenant_id=get_current_tenant_id() AND has_tenant_permission(get_current_tenant_id(),'users:update')) WITH CHECK(tenant_id=get_current_tenant_id() AND has_tenant_permission(get_current_tenant_id(),'users:update'));
COMMIT;
